    const nextRootNode: OrchestrationV2ExecutionNode = {
      id: nextRootNodeId,
      threadId: input.command.threadId,
      runId: targetRun.id,
      parentNodeId: null,
      rootNodeId: nextRootNodeId,
      kind: "root_turn",
      status: "pending",
      countsForRun: true,
      providerThreadId: restartProviderThread.id,
      providerTurnId: null,
      nativeItemRef: null,
      runtimeRequestId: null,
