        assert.deepEqual(
          yield* sql`SELECT name FROM effect_sql_migrations WHERE migration_id = 44`,
          [{ name: legacyNames[0] }],
        );
      }).pipe(Effect.provide(NodeSqliteClient.layer({ filename: source })));
    }).pipe(Effect.scoped, Effect.provide(NodeServices.layer)),
);

