export const migrationManifest = migrationEntries.map(([id, name]) => [id, name] as const);

const makeMigrationLoader = (throughId?: number) =>
  Migrator.fromRecord(
    Object.fromEntries(
      migrationEntries
        .filter(([id]) => throughId === undefined || id <= throughId)
        .map(([id, name, migration]) => [`${id}_${name}`, migration]),
    ),
  );

const FIRST_V2_MIGRATION_ID = 55;

// Migrators skip ids up to the highest recorded; reject collisions that would skip V2 schema.
const assertV2MigrationsCanRun = Effect.fn("assertV2MigrationsCanRun")(function* (
  throughId?: number,
) {
  const sql = yield* SqlClient.SqlClient;
  const tables = yield* sql`
    SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'effect_sql_migrations'
  `;
  if (tables.length === 0) return;
  const recorded = yield* sql<{
    readonly migration_id: number;
    readonly name: string;
  }>`SELECT migration_id, name FROM effect_sql_migrations`;
  const latestRecordedId = Math.max(0, ...recorded.map((row) => row.migration_id));
  const recordedNames = new Map(recorded.map((row) => [row.migration_id, row.name]));
  const skipped = migrationEntries.flatMap(([id, name]) => {
    if (
      id < FIRST_V2_MIGRATION_ID ||
      id > latestRecordedId ||
      (throughId !== undefined && id > throughId)
    )
      return [];
    const recordedName = recordedNames.get(id);
    if (recordedName === name) return [];
    return [`${id}_${name} (recorded: ${recordedName ?? "nothing"})`];
  });
  if (skipped.length === 0) return;
  return yield* new Migrator.MigrationError({
    kind: "BadState",
    message: `This database's migration history would skip required schema migrations: ${skipped.join(", ")}. The migrator skips every id up to the highest recorded id (${latestRecordedId}), regardless of name. It was probably written by a different build. Start the build that wrote it, or report this migration history so an upgrade path can be added.`,
  });
});

const run = Migrator.make({});

export interface RunMigrationsOptions {
  readonly toMigrationInclusive?: number | undefined;
}

export const runMigrations = Effect.fn("runMigrations")(function* ({
  toMigrationInclusive,
}: RunMigrationsOptions = {}) {
  const sql = yield* SqlClient.SqlClient;
  return yield* sql.withTransaction(
    Effect.gen(function* () {
      const includesV2 =
        toMigrationInclusive === undefined || toMigrationInclusive >= FIRST_V2_MIGRATION_ID;
      const previewMigrations = includesV2 ? yield* reconcileV2PreviewMigration() : [];
      if (includesV2) {
        yield* assertV2MigrationsCanRun(toMigrationInclusive);
      }
      const repaired = yield* bridgeLegacyForkMigrations(migrationManifest, toMigrationInclusive);
      const executedMigrations = [
        ...repaired,
        ...previewMigrations,
        ...(yield* run({ loader: makeMigrationLoader(toMigrationInclusive) })),
      ];
      if (toMigrationInclusive === undefined) yield* runForkMigrations();
      const migrations = executedMigrations.map(([id, name]) => `${id}_${name}`);
      yield* migrations.length === 0
        ? Effect.logDebug("Database schema is current")
        : Effect.log("Migrations ran successfully").pipe(Effect.annotateLogs({ migrations }));

      const recorded = yield* sql<{
        readonly migration_id: number;
        readonly name: string;
      }>`SELECT migration_id, name FROM effect_sql_migrations`;
      const manifestNames = new Map<number, string>(
        migrationEntries.map(([id, name]) => [id, name]),
      );
      const expectedHistory = migrationManifest.filter(
        ([id]) => toMigrationInclusive === undefined || id <= toMigrationInclusive,
      );
      if (
        expectedHistory.some(
          ([id, name]) => !recorded.some((row) => row.migration_id === id && row.name === name),
        )
      ) {
        return yield* new Migrator.MigrationError({
          kind: "BadState",
          message: "Upstream migration history did not reach the required version.",
        });
      }
      const divergent = recorded.flatMap((row) => {
        const expected = manifestNames.get(row.migration_id);
        if (expected === undefined) {
          return [`${row.migration_id}:${row.name} (unknown to this build)`];
        }
        return expected === row.name
          ? []
          : [`${row.migration_id}:${row.name} (this build: ${expected})`];
      });
      if (divergent.length > 0) {
        yield* Effect.logWarning(
          "Database migration history diverges from this build; recorded migration ids are skipped, not reconciled by name.",
        ).pipe(Effect.annotateLogs({ divergent }));
      }
      return executedMigrations;
    }),
  );
});

