        yield* Deferred.succeed(h.controls.gate, undefined);
        expect((yield* Fiber.join(stale).pipe(Effect.flip)).reason).toBe("conflict");
        expect((yield* h.service.state).status).toBe("unavailable");
      }).pipe(Effect.provide(base)),
