        yield* bootstrap(b, B);
        yield* h.awaitState((s) => aggregateAttention(s).complete);
        const entryA = Option.getOrThrow(Option.fromUndefinedOr(h.initial.get(A)));
        yield* SubscriptionRef.set(h.entries, new Map([[A, { ...entryA, enabled: false }]]));
        yield* h.awaitState((s) => s.environments.size === 0);
        yield* Deferred.await(a.closed);
        yield* Deferred.await(b.closed);
        yield* SubscriptionRef.set(h.entries, new Map([[A, entryA]]));
        const enabled = yield* Queue.take(h.remote(A).calls);
        expect(enabled.input.cursor).toBeUndefined();
        expect(aggregateAttention(yield* SubscriptionRef.get(h.state)).itemCount).toBe(0);
        yield* bootstrap(enabled, A);
        yield* h.awaitStatus(A, "live");
        yield* SubscriptionRef.set(
          h.entries,
          new Map([
            [
              A,
              {
                ...entryA,
                target: new PrimaryConnectionTarget({
                  environmentId: A,
                  label: "Changed target",
                  httpBaseUrl: "https://changed.test",
                  wsBaseUrl: "wss://changed.test",
                }),
              },
            ],
          ]),
        );
        const replacement = yield* Queue.take(h.remote(A).calls);
        yield* Deferred.await(enabled.closed);
        expect(replacement.input.cursor).toBeUndefined();
        yield* bootstrap(replacement, A, []);
        expect(aggregateAttention(yield* h.awaitStatus(A, "live")).itemCount).toBe(0);
      }),
  );

  it.effect(
    "waits for the supervisor after transport loss and exposes unsupported capability without subscribing",
    () =>
      Effect.gen(function* () {
        const h = yield* makeHarness([A]);
        const call = yield* Queue.take(h.remote(A).calls);
        yield* bootstrap(call, A);
        yield* h.awaitStatus(A, "live");
        yield* Queue.fail(
          call.messages,
          new RpcClientError.RpcClientError({
            reason: new RpcClientError.RpcClientDefect({ message: "Disconnected", cause: null }),
          }),
        );
        yield* h.awaitStatus(A, "stale");
        yield* TestClock.adjust("1 hour");
        expect(yield* SubscriptionRef.get(h.remote(A).subscriptions)).toBe(1);
        const unsupported = yield* makeSession(A, false);
        yield* SubscriptionRef.set(h.supervisor(A).session, Option.some(unsupported.session));
        const state = yield* h.awaitStatus(A, "unsupported");
        expect(aggregateAttention(state)).toMatchObject({ itemCount: 0, complete: false });
        expect(yield* SubscriptionRef.get(unsupported.subscriptions)).toBe(0);
      }),
  );

  it.effect("rejects mismatched frames and protocol faults without resubscription loops", () =>
    Effect.gen(function* () {
      const h = yield* makeHarness([A]);
      const call = yield* Queue.take(h.remote(A).calls);
      yield* bootstrap(call, B);
      yield* h.awaitStatus(A, "error");
      yield* TestClock.adjust("1 hour");
      expect(yield* SubscriptionRef.get(h.remote(A).subscriptions)).toBe(1);
      const replacement = yield* makeSession(A);
      yield* SubscriptionRef.set(h.supervisor(A).session, Option.some(replacement.session));
      const next = yield* Queue.take(replacement.calls);
      yield* bootstrap(next, A);
      yield* h.awaitStatus(A, "live");
      yield* Queue.fail(
        next.messages,
        new AttentionSyncError({ reason: "cursor-scope-mismatch", message: "Wrong cursor" }),
      );
      const failed = yield* h.awaitStatus(A, "error");
      expect(aggregateAttention(failed)).toMatchObject({ complete: false, staleItemCount: 1 });
      yield* TestClock.adjust("1 hour");
      expect(yield* SubscriptionRef.get(replacement.subscriptions)).toBe(1);
    }),
  );

  it.effect(
    "cannot resurrect resolved items with duplicate/lower transport revisions or relay disagreement",
    () =>
      Effect.gen(function* () {
        const h = yield* makeHarness([A]);
        const call = yield* Queue.take(h.remote(A).calls);
        yield* bootstrap(call, A);
        yield* h.awaitStatus(A, "live");
        const removed = delta(A, 2, [{ key: change().key, version: 2, entity: null }]);
        yield* Queue.offer(call.messages, removed);
        const resolved = yield* h.awaitState(
          (s) => aggregateAttention(s).complete && aggregateAttention(s).itemCount === 0,
        );
        expect(
          selectAttentionRelayHints(resolved, [hint(A, "2099-01-01T00:00:00Z")]).hints.size,
        ).toBe(0);
        yield* Queue.offer(call.messages, { ...removed, changes: [change()] });
        yield* Queue.offer(call.messages, delta(A, 3, [change()]));
        const rejected = yield* h.awaitStatus(A, "error");
        expect(aggregateAttention(rejected).itemCount).toBe(0);
      }),
  );
});

import { WS_METHODS, type EnvironmentId } from "@t3tools/contracts";
import * as Cause from "effect/Cause";
import * as Effect from "effect/Effect";
import * as Equal from "effect/Equal";
import * as Exit from "effect/Exit";
import * as Fiber from "effect/Fiber";
import * as HashMap from "effect/HashMap";
import * as Option from "effect/Option";
import * as Stream from "effect/Stream";
import * as SubscriptionRef from "effect/SubscriptionRef";
import { AsyncResult, Atom } from "effect/reactivity";
import {
  attentionSyncFailed,
  emptyAttentionSync,
  reduceAttentionStream,
} from "../attentionSync.ts";
import type { ConnectionCatalogEntry } from "../connection/catalog.ts";
import type { SupervisorConnectionState } from "../connection/model.ts";
import { EnvironmentRegistry } from "../connection/registry.ts";
import { EnvironmentSupervisor } from "../connection/supervisor.ts";
import { EnvironmentRpcSubscriptionObserver, isRpcClientError } from "../rpc/client.ts";
import type { RpcSession } from "../rpc/session.ts";
import { projectAttentionNotifications } from "./attentionNotifications.ts";
import {
  aggregateAttention,
  emptyEnvironmentAttention,
  type AttentionWorkspaceState,
  type EnvironmentAttentionState,
} from "./attentionProjection.ts";

function authorizationLost(state: SupervisorConnectionState) {
  return (
    state.phase === "blocked" &&
    (state.lastFailure?.reason === "authentication" || state.lastFailure?.reason === "permission")
  );
}

/** Owns only a subscription; connection lifecycle belongs to the existing supervisor. */
export const makeEnvironmentAttentionState = Effect.fn("makeEnvironmentAttentionState")(
  function* () {
    const supervisor = yield* EnvironmentSupervisor;
    const observer = yield* EnvironmentRpcSubscriptionObserver;
    const environmentId = supervisor.target.environmentId;
    const state = yield* SubscriptionRef.make(emptyEnvironmentAttention());
    let sync = emptyAttentionSync();

    const clear = Effect.fn(function* (
      status: "unauthorized" | "unsupported" | "error",
      reason: string,
    ) {
      sync = emptyAttentionSync();
      yield* SubscriptionRef.set(state, { ...emptyEnvironmentAttention(), status, reason });
    });
    const markStale = (reason: string) =>
      SubscriptionRef.update(state, (current): EnvironmentAttentionState => ({
        ...current,
        status:
          current.status === "unauthorized"
            ? "unauthorized"
            : current.hasSnapshot
              ? "stale"
              : "loading",
        reason: current.status === "unauthorized" ? "unauthorized" : reason,
        notificationCandidates: HashMap.empty(),
      }));
    const ownsSession = Effect.fn(function* (session: RpcSession) {
      const active = yield* SubscriptionRef.get(supervisor.session);
      return (
        Option.isSome(active) &&
        active.value === session &&
        !authorizationLost(yield* SubscriptionRef.get(supervisor.state))
      );
    });

    const consume = Effect.fn("attention.consumeSession")(function* (session: RpcSession) {
      // The delivery token binds server-side authentication, not just environment ID.
      // A replacement RPC session must establish a fresh fence before reusing authority.
      sync = emptyAttentionSync();
      yield* SubscriptionRef.update(state, (current): EnvironmentAttentionState => ({
        ...current,
        status: current.hasSnapshot ? "syncing" : "loading",
        reason: null,
        notificationCandidates: HashMap.empty(),
      }));
      const config = yield* Effect.exit(session.initialConfig);
      if (!(yield* ownsSession(session))) return;
      if (Exit.isFailure(config)) {
        if (Cause.hasInterrupts(config.cause)) return yield* Effect.interrupt;
        if (
          config.cause.reasons.some(
            (reason) =>
              reason._tag === "Fail" &&
              reason.error._tag === "ConnectionBlockedError" &&
              (reason.error.reason === "authentication" || reason.error.reason === "permission"),
          )
        ) {
          yield* clear("unauthorized", "unauthorized");
        } else {
          yield* markStale("configuration-unavailable");
        }
        yield* Effect.logWarning("Attention configuration unavailable.", { environmentId });
        return;
      }
      if (config.value.environment.environmentId !== environmentId) {
        yield* clear("error", "environment-mismatch");
        yield* Effect.logWarning("Attention configuration environment mismatch.", {
          environmentId,
        });
        return;
      }
      if (config.value.environment.capabilities.attentionSync !== true) {
        yield* clear("unsupported", "attention-sync-unsupported");
        return;
      }

      let failures = 0;
      while (yield* ownsSession(session)) {
        let retry = false;
        let terminal = false;
        const input =
          sync.cursor !== null && sync.status === "stale" ? { cursor: sync.cursor } : {};
        const completeObservation = yield* observer.observe({
          environmentId,
          method: WS_METHODS.attentionSubscribe,
          input,
        });
        // oxlint-disable-next-line t3code/no-rpc-permission-bypass -- This owned read-only stream must stay on the exact authenticated session; the observer and server scope checks still apply.
        const result = yield* session.client[WS_METHODS.attentionSubscribe](input).pipe(
          Stream.tap((message) =>
            Effect.gen(function* () {
              if (retry || terminal) return;
              if (!(yield* ownsSession(session))) {
                terminal = true;
                return;
              }
              if (message.type !== "reset-required" && message.environmentId !== environmentId) {
                yield* clear("error", "environment-mismatch");
                yield* Effect.logWarning("Attention stream environment mismatch.", {
                  environmentId,
                });
                terminal = true;
                return;
              }
              const before = sync;
              sync = reduceAttentionStream(sync, message);
              if (sync.status === "reset-required") {
                retry = message.type === "reset-required" && message.reason !== "message-too-large";
                terminal = !retry;
                yield* SubscriptionRef.update(state, (current): EnvironmentAttentionState => ({
                  ...current,
                  status: retry ? (current.hasSnapshot ? "stale" : "loading") : "error",
                  reason: sync.reason,
                  notificationCandidates: HashMap.empty(),
                }));
                yield* Effect.logWarning("Attention stream requires resynchronization.", {
                  environmentId,
                  reason: sync.reason,
                  retry,
                });
              } else if (sync.status === "live") {
                yield* SubscriptionRef.update(state, (current): EnvironmentAttentionState => ({
                  status: "live",
                  hasSnapshot: true,
                  entries: sync.entries,
                  reason: null,
                  notificationCandidates: projectAttentionNotifications(
                    current.notificationCandidates ?? HashMap.empty(),
                    before,
                    sync,
                    message,
                  ),
                }));
              } else if (message.type === "begin") {
                yield* SubscriptionRef.update(state, (current): EnvironmentAttentionState => ({
                  ...current,
                  status: current.hasSnapshot ? "syncing" : "loading",
                  reason: null,
                  notificationCandidates: HashMap.empty(),
                }));
              }
            }),
          ),
          Stream.takeUntil(() => retry || terminal),
          Stream.runDrain,
          Effect.ensuring(completeObservation),
          Effect.exit,
        );
        if (!(yield* ownsSession(session))) return;
        if (Exit.isFailure(result)) {
          if (Cause.hasInterrupts(result.cause)) return yield* Effect.interrupt;
          const failuresOnly = result.cause.reasons.filter((reason) => reason._tag === "Fail");
          const expected = failuresOnly.length === result.cause.reasons.length;
          const unauthorized = failuresOnly.some(
            (reason) => reason.error._tag === "EnvironmentAuthorizationError",
          );
          if (unauthorized) {
            yield* clear("unauthorized", "unauthorized");
            yield* Effect.logWarning("Attention access revoked.", { environmentId });
            return;
          }
          const transport =
            expected &&
            failuresOnly.length > 0 &&
            failuresOnly.every((reason) => isRpcClientError(reason.error));
          const unavailable =
            expected &&
            failuresOnly.length > 0 &&
            failuresOnly.every(
              (reason) =>
                reason.error._tag === "AttentionSyncError" && reason.error.reason === "unavailable",
            );
          sync = attentionSyncFailed(sync, "disconnected");
          yield* Effect.logWarning("Attention subscription failed.", {
            environmentId,
            transport,
            unavailable,
          });
          if (transport) {
            yield* markStale("transport-unavailable");
            return;
          }
          if (!unavailable) {
            yield* SubscriptionRef.update(state, (current): EnvironmentAttentionState => ({
              ...current,
              status: "error",
              reason: "attention-protocol-error",
            }));
            return;
          }
          yield* markStale("attention-unavailable");
        } else if (terminal) {
          return;
        } else if (!retry) {
          sync = attentionSyncFailed(sync, "disconnected");
          yield* markStale("stream-ended");
          yield* Effect.logWarning("Attention subscription ended before its connection.", {
            environmentId,
          });
        }
        yield* Effect.sleep([3_000, 4_000, 8_000, 16_000][Math.min(failures++, 3)]!);
      }
    });

    yield* Stream.merge(
      SubscriptionRef.changes(supervisor.session),
      SubscriptionRef.changes(supervisor.state),
    ).pipe(
      Stream.mapEffect(() =>
        Effect.gen(function* () {
          const session = yield* SubscriptionRef.get(supervisor.session);
          const unauthorized = authorizationLost(yield* SubscriptionRef.get(supervisor.state));
          return { session: Option.getOrNull(session), unauthorized };
        }),
      ),
      Stream.changesWith(
        (left, right) => left.session === right.session && left.unauthorized === right.unauthorized,
      ),
      Stream.switchMap(({ session, unauthorized }) =>
        Stream.fromEffect(
          unauthorized
            ? clear("unauthorized", "unauthorized")
            : session !== null
              ? consume(session)
              : Effect.gen(function* () {
                  sync = attentionSyncFailed(sync, "disconnected");
                  yield* markStale("disconnected");
                }),
        ),
      ),
      Stream.runDrain,
      Effect.forkScoped,
    );
    return state;
  },
);

const EMPTY_WORKSPACE: AttentionWorkspaceState = { isReady: false, environments: new Map() };

export const makeAttentionWorkspaceState = Effect.fn("makeAttentionWorkspaceState")(function* () {
  const registry = yield* EnvironmentRegistry;
  const state = yield* SubscriptionRef.make(EMPTY_WORKSPACE);
  const workers = new Map<
    EnvironmentId,
    {
      entry: ConnectionCatalogEntry;
      fiber?: Fiber.Fiber<void, never>;
    }
  >();
  yield* SubscriptionRef.changes(registry.entries).pipe(
    Stream.runForEach((entries) =>
      Effect.gen(function* () {
        const retired = [...workers].filter(
          ([id, worker]) =>
            !entries.get(id)?.enabled || !Equal.equals(entries.get(id), worker.entry),
        );
        for (const [id] of retired) workers.delete(id);
        yield* SubscriptionRef.update(state, (current) => ({
          isReady: true,
          environments: new Map(
            [...entries]
              .filter(([, entry]) => entry.enabled)
              .map(([id]) => [
                id,
                workers.has(id)
                  ? (current.environments.get(id) ?? emptyEnvironmentAttention())
                  : emptyEnvironmentAttention(),
              ]),
          ),
        }));
        yield* Effect.forEach(
          retired,
          ([, worker]) =>
            worker.fiber === undefined ? Effect.void : Fiber.interrupt(worker.fiber),
          {
            discard: true,
          },
        );
        for (const [id, entry] of entries) {
          if (!entry.enabled || workers.has(id)) continue;
          const worker: { entry: ConnectionCatalogEntry; fiber?: Fiber.Fiber<void, never> } = {
            entry,
          };
          workers.set(id, worker);
          worker.fiber = yield* registry
            .runStream(
              id,
              Stream.unwrap(
                makeEnvironmentAttentionState().pipe(Effect.map(SubscriptionRef.changes)),
              ),
            )
            .pipe(
              Stream.runForEach((value) =>
                SubscriptionRef.update(state, (current) => {
                  if (workers.get(id) !== worker) return current;
                  const environments = new Map(current.environments);
                  environments.set(id, value);
                  return { ...current, environments };
                }),
              ),
              Effect.catchTags({
                EnvironmentNotRegisteredError: Effect.fn("attention.environmentUnavailable")(
                  function* () {
                    if (!(yield* SubscriptionRef.get(registry.entries)).get(id)?.enabled) return;
                    yield* Effect.logWarning("Attention environment is no longer registered.", {
                      environmentId: id,
                    });
                    yield* SubscriptionRef.update(state, (current) => {
                      if (workers.get(id) !== worker) return current;
                      const environments = new Map(current.environments);
                      environments.set(id, {
                        ...emptyEnvironmentAttention(),
                        status: "error",
                        reason: "environment-unavailable",
                      });
                      return { ...current, environments };
                    });
                  },
                ),
              }),
              Effect.forkScoped,
            );
        }
      }),
    ),
    Effect.forkScoped,
  );
  return state;
});

/** One shared workspace atom owns all enabled-environment subscriptions for its consumers. */
export function createAttentionWorkspaceAtoms<R, E>(
  runtime: Atom.AtomRuntime<EnvironmentRegistry | R, E>,
) {
  const stateAtom = runtime.atom(
    Stream.unwrap(makeAttentionWorkspaceState().pipe(Effect.map(SubscriptionRef.changes))),
    { initialValue: EMPTY_WORKSPACE },
  );
  const valueAtom = Atom.make((get) =>
    Option.getOrElse(AsyncResult.value(get(stateAtom)), () => EMPTY_WORKSPACE),
  ).pipe(Atom.withLabel("attention-workspace"));
  const aggregateAtom = Atom.make((get) => aggregateAttention(get(valueAtom))).pipe(
    Atom.withLabel("attention-aggregate"),
  );
  return { stateAtom, valueAtom, aggregateAtom };
}

export * from "./attentionProjection.ts";

import { describe, expect, it } from "vite-plus/test";
import {
  ApprovalRequestId,
  AttentionDeliveryCursor,
  AttentionId,
  AttentionPageToken,
  EnvironmentId,
  EventId,
  ProjectId,
  ThreadId,
  TurnId,
  type AttentionChange,
  type AttentionStreamMessage,
} from "@t3tools/contracts";
import * as HashMap from "effect/HashMap";
import { emptyAttentionSync, reduceAttentionStream } from "../attentionSync.ts";
import { projectAttentionNotifications } from "./attentionNotifications.ts";

const checkpoint = (position: number) => ({
  environmentId: EnvironmentId.make("env"),
  generation: "generation",
  position,
  cursor: AttentionDeliveryCursor.make(`cursor-${position}`),
});
const item = (id = "a", revision = 1, version = revision): AttentionChange => ({
  key: `item:${id.repeat(64)}`,
  version,
  entity: {
    type: "item",
    value: {
      attentionId: AttentionId.make(id.repeat(64)),
      projectId: ProjectId.make("project"),
      threadId: ThreadId.make("thread"),
      turnId: null,
      requestId: ApprovalRequestId.make(id),
      kind: "approval",
      status: "open",
      reasonCode: "approval_requested",
      revision,
      sourceEventId: EventId.make(`event-${version}`),
      sourceSequence: version,
      openedAt: "2026-09-28T00:00:00Z",
      updatedAt: "2026-09-28T00:00:00Z",
      resolvedAt: null,
    },
  },
});
const summary = (
  version: number,
  phase: "running" | "completed",
  turn = "turn",
): AttentionChange => ({
  key: "summary:thread",
  version,
  entity: {
    type: "summary",
    value: {
      threadId: ThreadId.make("thread"),
      projectId: ProjectId.make("project"),
      turnId: TurnId.make(turn),
      phase,
      revision: version,
      approvalCount: 0,
      inputCount: 0,
      failureCount: 0,
      disconnectCount: 0,
      countsOverflowed: false,
      sourceEventId: EventId.make(`event-${version}`),
      sourceSequence: version,
      updatedAt: "2026-09-28T00:00:00Z",
    },
  },
});
function harness() {
  let state = emptyAttentionSync();
  let notifications = HashMap.empty<string, AttentionChange>();
  const send = (message: AttentionStreamMessage) => {
    const before = state;
    state = reduceAttentionStream(state, message);
    notifications = projectAttentionNotifications(notifications, before, state, message);
  };
  const delta = (position: number, changes: AttentionChange[], notificationEligible = true) =>
    send({
      ...checkpoint(position),
      type: "delta",
      after: state.cursor ?? checkpoint(0).cursor,
      notificationEligible,
      changes,
    });
  const bootstrap = (entries: AttentionChange[] = [], position = 0) => {
    send({ ...checkpoint(position), type: "begin", mode: "snapshot" });
    send({
      ...checkpoint(position),
      type: "page",
      pageToken: AttentionPageToken.make("page"),
      previousPageToken: null,
      entries,
    });
    send({ ...checkpoint(position), type: "sync-complete" });
  };
  return { send, delta, bootstrap, candidates: () => [...HashMap.values(notifications)] };
}
describe("attention notification eligibility", () => {
  it("does not notify snapshots, replay or rebuild but retains independent post-live candidates across batching", () => {
    const h = harness();
    h.bootstrap([item("a"), summary(1, "completed")], 1);
    expect(h.candidates()).toEqual([]);
    h.delta(2, [item("b", 1, 2)]);
    h.delta(3, [item("c", 1, 3)]);
    h.delta(4, []);
    expect(
      h
        .candidates()
        .map((row) => row.key)
        .sort(),
    ).toEqual([item("b").key, item("c").key]);
    h.send({ ...checkpoint(4), type: "begin", mode: "resume" });
    h.delta(5, [item("d", 1, 5)], false);
    h.send({ ...checkpoint(5), type: "sync-complete" });
    expect(h.candidates()).toEqual([]);
    h.send({ type: "reset-required", reason: "rebuilding" });
    h.bootstrap([item("f", 1, 6)], 6);
    expect(h.candidates()).toEqual([]);
  });
  it("removes resolved/deleted candidates and consumes only accepted material revisions", () => {
    const h = harness();
    h.bootstrap();
    h.delta(1, [item()]);
    h.delta(2, [item("a", 2, 2)]);
    expect(h.candidates()).toEqual([item("a", 2, 2)]);
    h.send({
      ...checkpoint(2),
      type: "delta",
      after: checkpoint(1).cursor,
      notificationEligible: true,
      changes: [item()],
    });
    expect(h.candidates()).toEqual([item("a", 2, 2)]);
    h.delta(3, [{ key: item().key, version: 3, entity: null }]);
    expect(h.candidates()).toEqual([]);
    h.delta(4, [item("b", 1, 4)], false);
    expect(h.candidates()).toEqual([]);
  });
  it("notifies a completion transition once, never subsequent same-turn revisions or a replayed completion", () => {
    const h = harness();
    h.bootstrap([summary(1, "completed")], 1);
    h.delta(2, [summary(2, "completed")]);
    expect(h.candidates()).toEqual([]);
    h.delta(3, [summary(3, "running", "next")]);
    h.delta(4, [summary(4, "completed", "next")]);
    h.delta(5, [summary(5, "completed", "next")]);
    expect(h.candidates()).toEqual([summary(4, "completed", "next")]);
    h.delta(6, [summary(6, "running", "third")]);
    expect(h.candidates()).toEqual([]);
  });
});

import type { AttentionChange, AttentionStreamMessage } from "@t3tools/contracts";
import * as HashMap from "effect/HashMap";
import * as Option from "effect/Option";
import type { AttentionSyncState } from "../attentionSync.ts";

/** Retains eligible current entities across consumer batching, not an event backlog. */
export function projectAttentionNotifications(
  candidates: HashMap.HashMap<string, AttentionChange>,
  before: AttentionSyncState,
  after: AttentionSyncState,
  message: AttentionStreamMessage,
) {
  if (after.status !== "live" || message.type === "sync-complete")
    return HashMap.empty<string, AttentionChange>();
  if (message.type !== "delta" || message.position <= before.position) return candidates;
  let next = candidates;
  for (const change of message.changes) {
    const old = HashMap.get(before.entries, change.key);
    if (Option.isSome(old) && old.value.version >= change.version) continue;
    const entity = change.entity;
    if (
      !message.notificationEligible ||
      entity === null ||
      (entity.type === "item" ? entity.value.status !== "open" : entity.value.phase !== "completed")
    ) {
      next = HashMap.remove(next, change.key);
      continue;
    }
    if (entity.type === "summary") {
      const previous = Option.getOrNull(old)?.entity;
      if (entity.value.turnId === null) continue;
      if (
        previous?.type === "summary" &&
        previous.value.phase === "completed" &&
        previous.value.turnId === entity.value.turnId
      )
        continue;
    }
    next = HashMap.set(next, change.key, change);
  }
  return next;
}

import type {
  AttentionChange,
  EnvironmentId,
  ScopedProjectRef,
  ScopedThreadRef,
  ThreadAttentionItem,
  ThreadAwarenessSummary,
} from "@t3tools/contracts";
import { RelayAgentActivityAggregateRow } from "@t3tools/contracts/relay";
import * as HashMap from "effect/HashMap";
import * as Option from "effect/Option";
import * as Schema from "effect/Schema";
import { scopedProjectKey, scopedThreadKey, scopeThreadRef } from "../environment/scoped.ts";

export interface EnvironmentAttentionState {
  readonly status:
    | "loading"
    | "syncing"
    | "live"
    | "stale"
    | "unauthorized"
    | "unsupported"
    | "error";
  readonly hasSnapshot: boolean;
  readonly entries: HashMap.HashMap<string, AttentionChange>;
  readonly reason: string | null;
  readonly notificationCandidates?: HashMap.HashMap<string, AttentionChange>;
}

export const emptyEnvironmentAttention = (): EnvironmentAttentionState => ({
  status: "loading",
  hasSnapshot: false,
  entries: HashMap.empty(),
  reason: null,
});

export interface AttentionWorkspaceState {
  readonly isReady: boolean;
  readonly environments: ReadonlyMap<EnvironmentId, EnvironmentAttentionState>;
}

export interface AttentionSelection {
  readonly environmentIds?: ReadonlyArray<EnvironmentId>;
  readonly projects?: ReadonlyArray<ScopedProjectRef>;
  readonly threads?: ReadonlyArray<ScopedThreadRef>;
  readonly kinds?: ReadonlyArray<ThreadAttentionItem["kind"]>;
  readonly priorities?: ReadonlyArray<ScopedAttentionItem["priority"]>;
}

export interface ScopedAttentionItem {
  readonly key: string;
  readonly ref: ScopedThreadRef;
  readonly item: ThreadAttentionItem;
  readonly stale: boolean;
  readonly priority: "blocking-error" | "warning";
}

export interface ScopedAttentionSummary {
  readonly ref: ScopedThreadRef;
  readonly summary: ThreadAwarenessSummary;
  readonly stale: boolean;
}

const compareText = (left: string, right: string) => (left < right ? -1 : left > right ? 1 : 0);

/** Counts come from open items, not the server's saturated summary counts. */
export function aggregateAttention(
  state: AttentionWorkspaceState,
  selection: AttentionSelection = {},
) {
  const environments = new Map<EnvironmentId, EnvironmentAttentionState>();
  const projects = selection.projects && new Set(selection.projects.map(scopedProjectKey));
  const threads = selection.threads && new Set(selection.threads.map(scopedThreadKey));
  const items: ScopedAttentionItem[] = [];
  const summaries = new Map<string, ScopedAttentionSummary>();
  const liveThreads = new Set<string>();
  const staleThreads = new Set<string>();
  let liveItemCount = 0;
  let staleItemCount = 0;
  let complete = state.isReady;

  for (const [environmentId, environment] of state.environments) {
    if (selection.environmentIds && !selection.environmentIds.includes(environmentId)) continue;
    if (
      selection.projects &&
      !selection.projects.some((ref) => ref.environmentId === environmentId)
    )
      continue;
    if (selection.threads && !selection.threads.some((ref) => ref.environmentId === environmentId))
      continue;
    environments.set(environmentId, environment);
    complete &&= environment.status === "live";
    const stale = environment.status !== "live";
    for (const [, change] of environment.entries) {
      const entity = change.entity;
      if (entity === null) continue;
      const ref = scopeThreadRef(environmentId, entity.value.threadId);
      const threadKey = scopedThreadKey(ref);
      if (threads && !threads.has(threadKey)) continue;
      if (
        projects &&
        !projects.has(scopedProjectKey({ environmentId, projectId: entity.value.projectId }))
      )
        continue;
      if (entity.type === "summary") {
        summaries.set(threadKey, { ref, summary: entity.value, stale });
        continue;
      }
      const item = entity.value;
      if (item.status !== "open" || (selection.kinds && !selection.kinds.includes(item.kind)))
        continue;
      const priority = item.kind === "disconnect" ? "warning" : "blocking-error";
      if (selection.priorities && !selection.priorities.includes(priority)) continue;
      items.push({
        key: `${environmentId}:${item.attentionId}`,
        ref,
        item,
        stale,
        priority,
      });
      if (stale) {
        staleItemCount += 1;
        staleThreads.add(threadKey);
      } else {
        liveItemCount += 1;
        liveThreads.add(threadKey);
      }
    }
  }
  items.sort(
    (left, right) =>
      Number(left.priority === "warning") - Number(right.priority === "warning") ||
      Date.parse(left.item.openedAt) - Date.parse(right.item.openedAt) ||
      compareText(left.ref.environmentId, right.ref.environmentId) ||
      compareText(left.ref.threadId, right.ref.threadId) ||
      compareText(left.item.attentionId, right.item.attentionId),
  );
  return {
    complete,
    environments,
    items,
    summaries,
    itemCount: items.length,
    threadCount: liveThreads.size + staleThreads.size,
    liveItemCount,
    liveThreadCount: liveThreads.size,
    staleItemCount,
    staleThreadCount: staleThreads.size,
  };
}

const decodeHint = Schema.decodeUnknownOption(RelayAgentActivityAggregateRow);

/** Relay timestamps cannot compete with direct revisions, even after disconnection or deletion. */
export function selectAttentionRelayHints(
  state: AttentionWorkspaceState,
  input: ReadonlyArray<unknown>,
) {
  const hints = new Map<string, RelayAgentActivityAggregateRow>();
  let rejectedCount = 0;
  for (const value of input) {
    const decoded = decodeHint(value);
    if (Option.isNone(decoded) || !Number.isFinite(Date.parse(decoded.value.updatedAt))) {
      rejectedCount += 1;
      continue;
    }
    const hint = decoded.value;
    const environment = state.environments.get(hint.environmentId);
    if (
      !environment ||
      environment.hasSnapshot ||
      (environment.status !== "loading" && environment.status !== "unsupported")
    ) {
      rejectedCount += 1;
      continue;
    }
    const key = scopedThreadKey(scopeThreadRef(hint.environmentId, hint.threadId));
    const previous = hints.get(key);
    if (previous && Date.parse(previous.updatedAt) >= Date.parse(hint.updatedAt)) continue;
    hints.set(key, hint);
  }
  return { hints, rejectedCount };
}

