    ).toThrow();
    expect(() =>
      decodeListResult({
        ...LIST_RESULT,
        entries: [{ ...github, kind: "work-item" }],
      }),
    ).toThrow();
    expect(() =>
      decodeListResult({
        ...LIST_RESULT,
        entries: [{ ...github, repository: null }],
      }),
    ).toThrow();
    expect(() =>
      decodeListResult({
        ...LIST_RESULT,
        entries: [{ ...azure, repository: "example/repo" }],
      }),
    ).toThrow();
  });
});

